const w = $json || {};
// بلا تاريخ النافذة الـAPI بترجّع الكتالوج كله. نوقف قبل النداء مش بعده.
if (!w.since_cairo || !/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(w.since_cairo)) {
  throw new Error('نافذة المزامنة مش صالحة: ' + JSON.stringify(w).slice(0, 300));
}
const notes = [];
// capped = المزامنة كانت واقفة أطول من السقف، فالنافذة مابتغطّيش الفجوة كلها
if (w.capped) notes.push('النافذة اتقصّت عند 6 ساعة — اللقطة الكاملة لازمة');
if (w.cold)   notes.push('فرع من غير أي ختم كتابة — بداية بارد');
if (notes.length) console.log(notes.join(' · '));
return [{ json: { since: w.since_cairo, gap_minutes: w.gap_minutes,
                  capped: !!w.capped, cold: !!w.cold,
                  // أسماء الأكواد اللي بتتجاب بالاسم بدل الكود
                  heavy: w.heavy || {},
                  oldest: w.oldest || null, notes: notes } }];

// رد الـAPI ممكن يكون Fail في body بـ200 — لازم يوقف هنا قبل ما «اختيار» يفتكر مفيش تغيير
for (const src of ['تغيّرات الكمية', 'تغيّرات الصنف']) {
  const o = $(src).first().json;
  if (o.Error || String(o.Message).toLowerCase() === 'fail') {
    throw new Error('eplus رفض «' + src + '»: ' + (o.Error || o.Message));
  }
}

/* stock_refresh_pick قارن تاريخ آخر حركة/تعديل في eplus بالمحفوظ في
   stock_mamora ورجّع اللي eplus عنده أحدث بس (الأقدم الأول، بحد 60).
   الصنف اللي يفشل بحثه بيفضل تاريخه القديم عندنا، فبيرجع هنا في الجولة
   الجاية لوحده — مفيش طابور تاني.

   البحث في eplus **جزئي** بالكود وبالاسم، فالنص الأطول أرخص:
   كود '6' بيرجّع ~15 ألف صنف، واسمه بيرجّع 1. التعادل للكود. */
const p = $json || {};
const pickName = (code, name) =>
  (name && String(name).trim().length > code.length) ? String(name).trim() : null;

const out = [], stuck = [];
for (const it of (p.items || [])) {
  const c = String(it.code).trim();
  if (!c) continue;
  const name = pickName(c, it.name);
  // كود خانة واحدة بلا اسم = البحث هيجيب نص الكتالوج؛ يستنى اللقطة الكاملة
  if (!name && c.length <= 1) { stuck.push(c); continue; }
  out.push({ json: { code: c, name: name, reason: it.reason, total: p.need } });
}

console.log('مرشّح ' + p.candidates + ' · محتاج تحديث ' + p.need + ' · الجولة دي ' + out.length +
  (p.need > out.length + stuck.length ? ' · الباقي للجولة الجاية ' + (p.need - out.length - stuck.length) : '') +
  (stuck.length ? ' · اتأجّل للّقطة: ' + stuck.join(',') : ''));
return out;

// الفروع المفتوحة للكتابة — نفس قايمة «نافذة» (مصدر واحد في البانى)
const BRANCHES_ON = ["mamora"];

const BR = {
  'الصيدلية':        'mamora',
  'ابراهيم حمدي 2':  'san',
  'ابراهيم حمدي 3':  'bishr',
  'السيوف':          'seyouf',
};

// الأكواد اللي طلبناها — بنفس ترتيب العناصر اللي دخلت «رصيد»
const askedList = $('أكواد').all().map(i => String(i.json.code));
const asked = new Set(askedList);

const map = new Map();   // مفتاح فرع|كود
const got = new Set();   // كود رجع فعلًا — حتى لو فرعه مقفول
const failed = [];       // أكواد البحث عنها فشل — بتتسجّل ومش بتوقف الجولة
let seen = 0, stray = 0;

$('رصيد').all().forEach((it, idx) => {
  const o = it.json || {};
  // صنف واحد فاشل مايوقعش الجولة كلها ويرمي نتايج الباقي
  if (o.error || o.Error || String(o.Message).toLowerCase() === 'fail') {
    failed.push(askedList[idx]);
    return;
  }
  for (const r of (o.Data || [])) {
    seen++;
    const code = String((r && r.itm_code) ?? '');
    // ⚠️ البحث جزئي: "7220" بيرجّع 57220 و72200 كمان. بناخد المطابق بس.
    if (!asked.has(code)) { stray++; continue; }
    got.add(code);
    const br = BR[r.sto_name];
    if (!br || BRANCHES_ON.indexOf(br) < 0) continue;
    map.set(br + '|' + code, r);
  }
});

if (failed.length) console.log('فشل ' + failed.length + ': ' + failed.slice(0, 30).join(','));
// لو أغلب الأصناف فشلت يبقى السيرفر واقع — نوقف من غير كتابة عشان المؤشّر مايتقدّمش
if (failed.length > askedList.length / 2) {
  throw new Error('أكتر من نص الأصناف فشلت (' + failed.length + ' من ' + askedList.length + ') — السيرفر غالبًا واقع');
}
if (map.size === 0) {
  throw new Error('ولا صف مطابق من ' + seen + ' صف رجعوا — راجع الفلترة');
}

// كود رجع منه ولا صف (ومش من الفاشلين) — غالبًا اسمه اتغيّر في eplus
const failedSet = new Set(failed);
const lost = askedList.filter(c => !got.has(c) && !failedSet.has(c));

const byBranch = {};
for (const [k, r] of map) {
  const br = k.split('|')[0];
  (byBranch[br] = byBranch[br] || []).push(r);
}

console.log('رجع ' + seen + ' صف · مطابق ' + map.size + ' · مرفوض ' + stray +
  ' · ' + Object.keys(byBranch).map(b => b + '=' + byBranch[b].length).join(' ') +
  (lost.length ? ' · مارجعش: ' + lost.slice(0, 20).join(',') : ''));

const out = [];
for (const br of Object.keys(byBranch)) {
  const list = byBranch[br];
  for (let i = 0; i < list.length; i += 2000) {
    out.push({ json: { p_branch: br, p_rows: list.slice(i, i + 2000) } });
  }
}
return out;
